            int distance_i = (int)projectile_render_vec2_t(
                projectile_pool[projectile_index].fields.origin_x - projectile_pool[projectile_index].fields.pos_x,
                projectile_pool[projectile_index].fields.origin_y
                    - projectile_pool[projectile_index].fields.pos_y).length();
            int divisor_i = (int)(
                projectile_pool[projectile_index].fields.speed_scale * 2.1f);
            int segment_count = distance_i / divisor_i;
            if (segment_count > 3) {
                segment_count = 3;
            }

            float heading = projectile_pool[projectile_index].angle + 1.5707964f;
            float step_x = (float)cos(heading)
                * projectile_pool[projectile_index].fields.speed_scale
                * 2.1f;
            float step_y = (float)sin(heading)
                * projectile_pool[projectile_index].fields.speed_scale
                * 2.1f;
            grim_interface_ptr->grim_set_color(
                0.3f, 1.0f, 0.3f, transition_alpha * 0.4f);
            for (int segment_index = 0;
                 segment_index < segment_count;
                 ++segment_index) {
                float segment = (float)segment_index;
                grim_interface_ptr->grim_draw_quad(
                    camera_offset_x + projectile_pool[projectile_index].fields.pos_x
                        + segment * step_x - 6.0f,
                    camera_offset_y + projectile_pool[projectile_index].fields.pos_y
                        + segment * step_y - 6.0f,
                    12.0f,
                    12.0f);
            }

            grim_interface_ptr->grim_set_color(
                0.3f, 1.0f, 0.3f, transition_alpha * 0.5f);
            grim_interface_ptr->grim_draw_quad(
                camera_offset_x + projectile_pool[projectile_index].fields.pos_x - 8.0f,
                camera_offset_y + projectile_pool[projectile_index].fields.pos_y - 8.0f,
                16.0f,
                16.0f);
            grim_interface_ptr->grim_set_color(
                0.3f, 1.0f, 0.3f, transition_alpha * 0.15f);
            if (config_blob.flame_glow_enabled) {
                grim_interface_ptr->grim_draw_quad(
                    camera_offset_x + projectile_pool[projectile_index].fields.pos_x - 60.0f,
                    camera_offset_y + projectile_pool[projectile_index].fields.pos_y - 60.0f,
                    120.0f,
                    120.0f);
            }
        } else if (type_id == PROJECTILE_TYPE_SHRINKIFIER) {
            int distance_i = (int)projectile_render_vec2_t(
                projectile_pool[projectile_index].fields.origin_x - projectile_pool[projectile_index].fields.pos_x,
                projectile_pool[projectile_index].fields.origin_y
                    - projectile_pool[projectile_index].fields.pos_y).length();
            int divisor_i = (int)(
                projectile_pool[projectile_index].fields.speed_scale * 2.1f);
            int segment_count = distance_i / divisor_i;
            if (segment_count > 3) {
                segment_count = 3;
            }

            float heading = projectile_pool[projectile_index].angle + 1.5707964f;
            float step_x = (float)cos(heading)
                * projectile_pool[projectile_index].fields.speed_scale
                * 2.1f;
            float step_y = (float)sin(heading)
                * projectile_pool[projectile_index].fields.speed_scale
                * 2.1f;
            grim_interface_ptr->grim_set_color(
                0.3f, 0.3f, 1.0f, transition_alpha * 0.4f);
            for (int segment_index = 0;
                 segment_index < segment_count;
                 ++segment_index) {
                float segment = (float)segment_index;
                grim_interface_ptr->grim_draw_quad(
                    camera_offset_x + projectile_pool[projectile_index].fields.pos_x
                        + segment * step_x - 6.0f,
                    camera_offset_y + projectile_pool[projectile_index].fields.pos_y
                        + segment * step_y - 6.0f,
                    12.0f,
                    12.0f);
            }

            grim_interface_ptr->grim_set_color(
                0.3f, 0.3f, 1.0f, transition_alpha * 0.5f);
            grim_interface_ptr->grim_draw_quad(
                camera_offset_x + projectile_pool[projectile_index].fields.pos_x - 8.0f,
                camera_offset_y + projectile_pool[projectile_index].fields.pos_y - 8.0f,
                16.0f,
                16.0f);
            grim_interface_ptr->grim_set_color(
                0.3f, 0.3f, 1.0f, transition_alpha * 0.15f);
            if (config_blob.flame_glow_enabled) {
                grim_interface_ptr->grim_draw_quad(
                    camera_offset_x + projectile_pool[projectile_index].fields.pos_x - 60.0f,
                    camera_offset_y + projectile_pool[projectile_index].fields.pos_y - 60.0f,
                    120.0f,
                    120.0f);
            }
        }
    } else {
        float fade = projectile_render_clamp(
            projectile_pool[projectile_index].fields.life_timer * 2.5f);
        grim_interface_ptr->grim_set_color(
            1.0f, 1.0f, 1.0f, fade * transition_alpha);
        grim_interface_ptr->grim_draw_quad(
            camera_offset_x + projectile_pool[projectile_index].fields.pos_x - 28.0f,
            camera_offset_y + projectile_pool[projectile_index].fields.pos_y - 28.0f,
            56.0f,
            56.0f);
    }
}
